import React, { useRef } from 'react';
import ReactPlayer from 'react-player'
import { motion } from 'framer-motion';
import { fadeIn } from '../variants';

const ShortVideos = ({reels}) => {
  const reelRef = useRef(reels.map(() => React.createRef()));
  const posterRef = useRef(reels.map(() => React.createRef()));
  function handleStart(index) {
    // console.log(posterRef.current[index].current);
    posterRef.current[index].current.className = 'video-bg';
    // console.log(index);
  }
  return (
    <motion.div 
    variants={fadeIn('up', 0.3)} initial="hidden"
    whileInView={'show'} viewport={{once: true, amount: 0}}
    className='socialmedia-container-mobile'>
              {
                reels.map((reelVideo, index)=> (
                  <a href={reelVideo.redirectLink} target='_blank'
                  key={index}
                  className={'socialmedia-card-01 group'+' down'}>
                    <div className='opacity-0 overlay'>
                      <div style={{ backgroundImage: `url(${reelVideo.logo})` }} className={'video-logo _3 '+reelVideo.dimension}> </div>
                      <div className='dark-bg'> </div>
                    </div>
                    <div className='videobg1 w-background-video w-background-video-atom'>
                      <img className='h-full w-full' src={reelVideo.poster} ref={posterRef && posterRef.current[index]} loading='lazy'/>
                      <ReactPlayer ref={reelRef && reelRef.current[index]} 
                      playing={true} 
                      onStart={() => handleStart(index)}
                      muted loop url={reelVideo.vimeoLink || [reelVideo.data.mp4, reelVideo.data.webm]}
                      width='100%' height='100%' playsinline
                      config={{
                        playerOptions: {
                          responsive: true,
                          fullscreen: true,
                      }
                      }}>
                      </ReactPlayer>
                    </div>
                  </a>
                ))
              }
    </motion.div>
  )
};

export default ShortVideos;
